<template>
  <F7Page class="!bg-transparent [&_.page-content]:!bg-transparent">
    <F7Navbar title="Messages" large :sliding="true">
      <template #nav-right>
        <div class="flex items-center gap-2 pr-3">
          <F7Link icon-only class="!w-10 !h-10" @click="onNewChat">
            <span
              class="glass-surface flex h-10 w-10 min-w-[40px] shrink-0 items-center justify-center rounded-[13px]"
            >
              <ILucidePlus class="h-[18px] w-[18px] text-ink-soft" />
            </span>
          </F7Link>
        </div>
      </template>
    </F7Navbar>

    <div class="relative z-10 min-h-screen bg-[#f5f9ff]">
      <div class="space-y-3 px-4 pb-[128px] pt-3">
        <MessengerSearchBar v-model="searchQuery" />
        <MessengerGroupTabs v-model="chatTag" />
        <MessengerChannelList :items="channels" @open="onOpen" />
      </div>
    </div>
  </F7Page>
</template>

<script setup lang="ts">
import { f7 } from "framework7-vue";
import MessengerSearchBar from "../components/MessengerSearchBar.vue";
import MessengerGroupTabs from "../components/MessengerGroupTabs.vue";
import MessengerChannelList from "../components/MessengerChannelList.vue";
import { useMessengerChannelList } from "../composables/useMessengerChannelList";

const { channels, searchQuery, chatTag, setOpenChannel } = useMessengerChannelList();

function onNewChat() {
  f7.toast.create({ text: "New conversation — coming soon", position: "top", closeTimeout: 2500 }).open();
}

function onOpen(channelId: number) {
  setOpenChannel(channelId);
  f7.toast.create({ text: "Conversation view — coming soon", position: "top", closeTimeout: 2500 }).open();
}
</script>
