import { onMounted } from "vue";
import { useMessengerChannels, useMessengerStore } from "@aybsig/messenger/vue";
import { ensureMessengerSetup } from "@/shared/services/messenger/messengerBootstrap";
import { formatChannelDate } from "../messenger.format";

export function useMessengerChannelList() {
  const store = useMessengerStore();
  const channels = useMessengerChannels();

  onMounted(() => {
    void ensureMessengerSetup();
    store.setOpenChannel(null);
  });

  return {
    ...channels,
    formatChannelDate,
    setOpenChannel: store.setOpenChannel,
  };
}
