<template>
  <button
    type="button"
    class="flex w-full items-center gap-3 rounded-2xl bg-white px-3 py-2.5 text-left transition-colors active:bg-[#eef3fb]"
    @click="emit('open', item.id)"
  >
    <MessengerChannelAvatar
      :name="item.name"
      :image-url="item.avatarUrl"
      :channel-type="item.channelType"
    />
    <div class="min-w-0 flex-1">
      <div class="flex items-center justify-between gap-2">
        <span class="truncate text-[15px] font-[760] text-[#090e24]">{{ item.name }}</span>
        <span class="shrink-0 text-[11px] font-medium text-[#9aa3bd]">
          {{ formatChannelDate(item.lastMessageDate) }}
        </span>
      </div>
      <div class="mt-0.5 flex items-center justify-between gap-2">
        <span
          class="truncate text-[13px]"
          :class="item.isTyping ? 'text-[#1f6df5]' : 'text-[#657096]'"
        >
          {{ previewText }}
        </span>
        <span
          v-if="item.unreadCount > 0"
          class="flex h-[18px] min-w-[18px] shrink-0 items-center justify-center rounded-full bg-[#1f6df5] px-1 text-[10px] font-[760] text-white"
        >
          {{ item.unreadCount }}
        </span>
      </div>
    </div>
  </button>
</template>

<script setup lang="ts">
import { computed } from "vue";
import type { ChannelListItem } from "@aybsig/messenger";
import MessengerChannelAvatar from "./MessengerChannelAvatar.vue";
import { formatChannelDate } from "../messenger.format";

const props = defineProps<{ item: ChannelListItem }>();
const emit = defineEmits<{ open: [channelId: number] }>();

const previewText = computed(() => {
  const item = props.item;
  if (item.isTyping) return item.typingName ? `${item.typingName} is typing…` : "typing…";
  const body = item.lastMessageBody ?? "";
  if (item.channelType === "channel" && item.lastMessageAuthor) {
    return `${item.lastMessageAuthor}: ${body}`;
  }
  return body;
});
</script>
